import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { test } from "node:test";
import type { SessionEventPayload } from "@wollipog/protocol";
import {
  parseClaudeSession,
  parseClaudeTranscript,
  parseCodexSession,
  parseCodexTranscript,
  stripClaudeNoise,
  stripCodexNoise,
} from "./parse.js";

/** Pull the first payload of a given kind for spot-checks (keeps assertions readable). */
function first<K extends SessionEventPayload["kind"]>(
  ev: SessionEventPayload[],
  kind: K,
): Extract<SessionEventPayload, { kind: K }> {
  const hit = ev.find((e) => e.kind === kind);
  assert.ok(hit, `expected a ${kind} event`);
  return hit as Extract<SessionEventPayload, { kind: K }>;
}

const NATIVE = { kind: "native" as const };

// Privacy-safe two-block context frame that reproduced the injected-context parsing regression.
// Preserve the envelope, heading/wrapper order, and block boundaries; never copy private guidance.
const GENERATED_AGENT_CONTEXT = readFileSync(
  new URL("./fixtures/generated-agent-context.jsonl", import.meta.url),
  "utf8",
);
const GENERATED_AGENT_CONTEXT_FILE =
  "rollout-2026-05-22T02-55-56-00000000-0000-7000-8000-000000000001.jsonl";

/* Real-shape fixtures (trimmed) of the two on-disk session stores. */

const CLAUDE = [
  `{"type":"queue-operation","operation":"enqueue","timestamp":"2026-06-27T12:56:26.210Z","sessionId":"d73c90f8-5a43-467e-82f4-960d4dc67a7a"}`,
  `{"parentUuid":null,"type":"user","cwd":"C:\\\\Users\\\\me\\\\repo","message":{"role":"user","content":[{"type":"text","text":"Create a file named HELLO.md"}]},"uuid":"ff15","timestamp":"2026-06-27T12:56:26.250Z"}`,
  `{"type":"assistant","timestamp":"2026-06-27T12:56:27.000Z","message":{"role":"assistant","content":[{"type":"text","text":"Done — created HELLO.md."}]}}`,
  `garbage line that is not json`,
].join("\n");
const CLAUDE_FILE = "d73c90f8-5a43-467e-82f4-960d4dc67a7a.jsonl";

// A session that opens with a local slash command (/model): Claude Code records the caveat +
// command wrappers as the FIRST user message, followed by the real prompt.
const CLAUDE_NOISY = [
  `{"type":"user","cwd":"C:\\\\Users\\\\me\\\\repo","message":{"role":"user","content":"<local-command-caveat>Caveat: The messages below were generated by the user while running local commands.</local-command-caveat>\\n<command-name>/model</command-name>\\n<command-args>opus</command-args>"},"timestamp":"2026-06-27T12:56:26.250Z"}`,
  `{"type":"user","message":{"role":"user","content":[{"type":"text","text":"Actually fix the bug in parser.ts"}]},"timestamp":"2026-06-27T12:56:27.000Z"}`,
  `{"type":"assistant","message":{"role":"assistant","content":[{"type":"text","text":"On it."}]}}`,
].join("\n");
const CLAUDE_NOISY_FILE = "aa11bb22-3344-5566-7788-99aabbccddee.jsonl";

const CODEX = [
  `{"timestamp":"2026-05-21T00:18:49.970Z","type":"session_meta","payload":{"id":"019e47e6-3480-7e52-ba8a-e97b85ef7857","timestamp":"2026-05-21T00:18:49.602Z","cwd":"C:\\\\Users\\\\me\\\\proj","cli_version":"0.131.0"}}`,
  `{"type":"event_msg","payload":{"type":"task_started"}}`,
  `{"type":"response_item","payload":{"type":"message","role":"user","content":[{"type":"input_text","text":"<environment_context>\\n  <cwd>C:\\\\Users\\\\me\\\\proj</cwd>\\n</environment_context>"}]}}`,
  `{"type":"response_item","payload":{"type":"message","role":"user","content":[{"type":"input_text","text":"Refactor the parser"}]}}`,
  `{"type":"event_msg","payload":{"type":"agent_message","message":"I'll refactor it now."}}`,
].join("\n");
const CODEX_FILE = "rollout-2026-05-21T00-18-49-019e47e6-3480-7e52-ba8a-e97b85ef7857.jsonl";

test("parseClaudeSession pulls id (from filename), cwd, title, count from the head", () => {
  const d = parseClaudeSession(CLAUDE, CLAUDE_FILE, 5000, NATIVE);
  assert.ok(d);
  assert.equal(d!.agentSessionId, "d73c90f8-5a43-467e-82f4-960d4dc67a7a");
  assert.equal(d!.driver, "claude-code");
  assert.equal(d!.cwd, "C:\\Users\\me\\repo");
  assert.equal(d!.title, "Create a file named HELLO.md");
  assert.equal(d!.messageCount, 2); // 1 user + 1 assistant
  assert.equal(d!.updatedAt, 5000);
  assert.equal(d!.createdAt, Date.parse("2026-06-27T12:56:26.210Z")); // first timestamped line
  assert.deepEqual(d!.context, NATIVE);
});

test("parseClaudeSession rejects a non-uuid filename", () => {
  assert.equal(parseClaudeSession(CLAUDE, "notes.jsonl", 1, NATIVE), null);
});

test("parseClaudeTranscript maps user/assistant text, skips internal + bad lines", () => {
  const ev = parseClaudeTranscript(CLAUDE);
  assert.deepEqual(ev, [
    { kind: "user_message", text: "Create a file named HELLO.md", final: true },
    { kind: "agent_message", text: "Done — created HELLO.md.", final: true },
  ]);
});

test("stripClaudeNoise removes local-command + system wrappers, keeps real text", () => {
  assert.equal(stripClaudeNoise("<local-command-caveat>Caveat: …</local-command-caveat>"), "");
  assert.equal(stripClaudeNoise("<command-name>/model</command-name>\n<command-args>opus</command-args>"), "");
  assert.equal(stripClaudeNoise("<system-reminder>be nice</system-reminder>\nReal prompt"), "Real prompt");
});

test("parseClaudeSession skips a leading local-command message and titles on the first real prompt", () => {
  const d = parseClaudeSession(CLAUDE_NOISY, CLAUDE_NOISY_FILE, 7000, NATIVE);
  assert.ok(d);
  assert.equal(d!.title, "Actually fix the bug in parser.ts"); // not the "<local-command-caveat>…" block
  assert.equal(d!.messageCount, 3); // 2 user + 1 assistant (the wrapper message still counts)
});

test("parseClaudeTranscript drops a pure local-command user turn, keeps the real turns", () => {
  const ev = parseClaudeTranscript(CLAUDE_NOISY);
  assert.deepEqual(ev, [
    { kind: "user_message", text: "Actually fix the bug in parser.ts", final: true },
    { kind: "agent_message", text: "On it.", final: true },
  ]);
});

test("parseCodexSession reads id/cwd/createdAt from session_meta and skips the env-context title", () => {
  const d = parseCodexSession(CODEX, CODEX_FILE, 9000, NATIVE);
  assert.ok(d);
  assert.equal(d!.agentSessionId, "019e47e6-3480-7e52-ba8a-e97b85ef7857");
  assert.equal(d!.driver, "codex");
  assert.equal(d!.cwd, "C:\\Users\\me\\proj");
  assert.equal(d!.createdAt, Date.parse("2026-05-21T00:18:49.602Z"));
  // The environment_context message strips to empty, so the title is the first REAL user prompt.
  assert.equal(d!.title, "Refactor the parser");
});

test("parseCodexSession falls back to the filename id when session_meta is absent", () => {
  const noMeta = `{"type":"event_msg","payload":{"type":"agent_message","message":"hi"}}`;
  const d = parseCodexSession(noMeta, CODEX_FILE, 1, NATIVE);
  assert.equal(d!.agentSessionId, "019e47e6-3480-7e52-ba8a-e97b85ef7857");
});

test("parseCodexTranscript maps agent + real user text, drops the env-context noise", () => {
  const ev = parseCodexTranscript(CODEX);
  assert.deepEqual(ev, [
    { kind: "user_message", text: "Refactor the parser", final: true },
    { kind: "agent_message", text: "I'll refactor it now.", final: true },
  ]);
});

test("generated AGENTS context is neither a title, user turn, nor counted message", () => {
  const descriptor = parseCodexSession(
    GENERATED_AGENT_CONTEXT,
    GENERATED_AGENT_CONTEXT_FILE,
    9_000,
    NATIVE,
  );
  assert.ok(descriptor);
  assert.equal(descriptor.title, "Fix the sample parser regression.");
  assert.equal(descriptor.messageCount, 2, "one meaningful user prompt plus one agent message");
  assert.equal(
    descriptor.cwd,
    "\\\\wsl.localhost\\Fixture-Distro\\home\\fixture\\dev\\sample",
  );

  const events = parseCodexTranscript(GENERATED_AGENT_CONTEXT);
  assert.deepEqual(events, [
    { kind: "user_message", text: "Fix the sample parser regression.", final: true },
    { kind: "agent_message", text: "I will fix the sample parser regression.", final: true },
  ]);
  assert.equal(JSON.stringify(events).includes("AGENTS.md"), false);
  assert.equal(JSON.stringify(events).includes("fixture-only guidance"), false);
});

test("stripCodexNoise removes injected wrappers", () => {
  assert.equal(
    stripCodexNoise(
      "# AGENTS.md instructions for /fixture/repo\n\n<INSTRUCTIONS>injected</INSTRUCTIONS>" +
      "<environment_context>cwd</environment_context>",
    ),
    "# AGENTS.md instructions for /fixture/repo\n\n<INSTRUCTIONS>injected</INSTRUCTIONS>",
  );
  assert.equal(stripCodexNoise("<INSTRUCTIONS># AGENTS.md instructions for repo</INSTRUCTIONS>\nactual"), "actual");
  assert.equal(
    stripCodexNoise("describe <instructions>keep this example</instructions> exactly"),
    "describe <instructions>keep this example</instructions> exactly",
  );
  assert.equal(
    stripCodexNoise("<environment_context>cwd</environment_context><INSTRUCTIONS>injected</INSTRUCTIONS>actual"),
    "actual",
  );
  assert.equal(stripCodexNoise("<recommended_plugins>plugin catalog</recommended_plugins>\nactual"), "actual");
  assert.equal(stripCodexNoise("<environment_context>x</environment_context>\nhello"), "hello");
  assert.equal(stripCodexNoise("<user_instructions>do x</user_instructions> plain"), "plain");
  assert.equal(stripCodexNoise('<subagent_notification>{"a":1}</subagent_notification> kept'), "kept");
  assert.equal(stripCodexNoise("just text"), "just text");
});

test("a user-authored AGENTS-shaped prompt is preserved without the generated multi-block envelope", () => {
  const prompt = "# AGENTS.md instructions for /fixture/repo\n\n<INSTRUCTIONS>quote this exactly</INSTRUCTIONS>";
  const content = [
    JSON.stringify({
      type: "session_meta",
      payload: { id: "019e47e6-3480-7e52-ba8a-e97b85ef7857", cwd: "/fixture/repo" },
    }),
    JSON.stringify({
      type: "response_item",
      payload: { type: "message", role: "user", content: [{ type: "input_text", text: prompt }] },
    }),
  ].join("\n");

  assert.equal(parseCodexSession(content, CODEX_FILE, 1, NATIVE)?.title, prompt.slice(0, 100));
  assert.deepEqual(parseCodexTranscript(content), [{ kind: "user_message", text: prompt, final: true }]);
});

test("parseCodexSession excludes each spawned-subagent metadata shape without hiding normal sessions", () => {
  const session = (metadata: Record<string, unknown>) => [
    JSON.stringify({
      type: "session_meta",
      payload: {
        id: "019e47e6-3480-7e52-ba8a-e97b85ef7858",
        cwd: "C:\\Users\\me\\proj",
        ...metadata,
      },
    }),
    JSON.stringify({
      type: "response_item",
      payload: { type: "message", role: "user", content: [{ type: "input_text", text: "<INSTRUCTIONS>injected</INSTRUCTIONS>" }] },
    }),
  ].join("\n");

  assert.equal(parseCodexSession(session({ thread_source: "subagent" }), CODEX_FILE, 1, NATIVE), null);
  assert.equal(
    parseCodexSession(
      session({ source: { subagent: { thread_spawn: { parent_thread_id: "019e47e6-3480-7e52-ba8a-e97b85ef7857" } } } }),
      CODEX_FILE,
      1,
      NATIVE,
    ),
    null,
  );
  assert.ok(parseCodexSession(session({ thread_source: "user", source: "exec" }), CODEX_FILE, 1, NATIVE));
});

test("parseCodexTranscript folds a subagent_notification into work, not a user message", () => {
  const subInner = JSON.stringify({ agent_path: "a1", status: { completed: "**Findings**\n- a real bug" } });
  const lines = [
    JSON.stringify({ type: "response_item", payload: { type: "message", role: "user", content: [{ type: "input_text", text: "Review the PR" }] } }),
    JSON.stringify({
      type: "response_item",
      payload: { type: "message", role: "user", content: [{ type: "input_text", text: `<subagent_notification>${subInner}</subagent_notification>` }] },
    }),
    JSON.stringify({ type: "event_msg", payload: { type: "agent_message", message: "Synthesizing the findings." } }),
  ].join("\n");
  const ev = parseCodexTranscript(lines);
  // the subagent result becomes reasoning (folds into the work block), NOT a second user bubble
  assert.deepEqual(
    ev.map((e) => e.kind),
    ["user_message", "agent_thought", "agent_message"],
  );
  assert.equal(first(ev, "user_message").text, "Review the PR");
  const thought = first(ev, "agent_thought");
  assert.match(thought.text, /Subagent result/);
  assert.match(thought.text, /a real bug/);
  assert.equal(ev.some((event) => event.kind === "tool_call" && event.toolKind === "agent"), false,
    "raw imports retain a truthful summary instead of fabricating selectable identity");
});

/* ---- Phase 1 chat-log fidelity: rich backfill (reasoning + tool calls + edits) ---- */

const CLAUDE_RICH = [
  `{"type":"user","message":{"role":"user","content":[{"type":"text","text":"Fix the bug"}]}}`,
  `{"type":"assistant","message":{"role":"assistant","content":[{"type":"thinking","thinking":"Read the file first."},{"type":"text","text":"On it."},{"type":"tool_use","id":"tu1","name":"Read","input":{"file_path":"/repo/a.ts"}}]}}`,
  `{"type":"user","message":{"role":"user","content":[{"type":"tool_result","tool_use_id":"tu1","content":"line1\\nline2"}]}}`,
  `{"type":"assistant","message":{"role":"assistant","content":[{"type":"tool_use","id":"tu2","name":"Edit","input":{"file_path":"/repo/a.ts","old_string":"x","new_string":"y"}}]}}`,
  `{"type":"user","message":{"role":"user","content":[{"type":"tool_result","tool_use_id":"tu2","content":"ok","is_error":false}]}}`,
].join("\n");

test("parseClaudeTranscript recovers thinking, tool calls, edits, and results", () => {
  const ev = parseClaudeTranscript(CLAUDE_RICH);
  assert.deepEqual(
    ev.map((e) => e.kind),
    ["user_message", "agent_thought", "agent_message", "tool_call", "tool_call_update", "tool_call", "file_edit", "tool_call_update"],
  );
  assert.equal(first(ev, "agent_thought").text, "Read the file first.");
  const read = first(ev, "tool_call");
  assert.equal(read.toolCallId, "tu1");
  assert.equal(read.title, "Read: /repo/a.ts");
  assert.equal(read.toolKind, "read");
  assert.equal(read.status, "completed");
  const result = first(ev, "tool_call_update");
  assert.equal(result.toolCallId, "tu1");
  assert.equal(result.text, "line1\nline2");
  assert.equal(first(ev, "file_edit").path, "/repo/a.ts");
});

test("parseClaudeTranscript preserves recursive parent attribution and normalizes Task as agent", () => {
  const content = [
    `{"type":"assistant","parent_tool_use_id":"outer","message":{"usage":{"input_tokens":7,"output_tokens":3,"cache_read_input_tokens":2},"content":[{"type":"thinking","thinking":"delegate"},{"type":"tool_use","id":"inner","name":"Task","input":{}}]}}`,
    `{"type":"assistant","parent_tool_use_id":"inner","message":{"content":[{"type":"text","text":"deep"},{"type":"tool_use","id":"edit","name":"Edit","input":{"file_path":"/repo/deep.ts"}}]}}`,
    `{"type":"user","parent_tool_use_id":"inner","message":{"content":[{"type":"tool_result","tool_use_id":"edit","content":"ok"}]}}`,
  ].join("\n");
  const events = parseClaudeTranscript(content);
  const inner = events.find((event) => event.kind === "tool_call" && event.toolCallId === "inner") as Extract<SessionEventPayload, { kind: "tool_call" }>;
  assert.equal(inner.toolKind, "agent");
  assert.equal(inner.parentToolUseId, "outer");
  const outerThought = events.find((event) => event.kind === "agent_thought") as Extract<SessionEventPayload, { kind: "agent_thought" }>;
  assert.equal(outerThought.parentToolUseId, "outer");
  const deep = events.find((event) => event.kind === "agent_message") as Extract<SessionEventPayload, { kind: "agent_message" }>;
  const edit = events.find((event) => event.kind === "file_edit") as Extract<SessionEventPayload, { kind: "file_edit" }>;
  const result = events.find((event) => event.kind === "tool_call_update") as Extract<SessionEventPayload, { kind: "tool_call_update" }>;
  const usage = events.find((event) => event.kind === "token_usage") as Extract<SessionEventPayload, { kind: "token_usage" }>;
  assert.equal(deep.parentToolUseId, "inner");
  assert.equal(edit.parentToolUseId, "inner");
  assert.equal(result.parentToolUseId, "inner");
  assert.deepEqual(usage, { kind: "token_usage", inputTokens: 7, outputTokens: 3, cachedInputTokens: 2, parentToolUseId: "outer" });
});

const CODEX_RICH = [
  `{"type":"session_meta","payload":{"id":"019e","cwd":"/p","timestamp":"2026-05-21T00:18:49.602Z"}}`,
  `{"type":"response_item","payload":{"type":"message","role":"user","content":[{"type":"input_text","text":"List files"}]}}`,
  `{"type":"response_item","payload":{"type":"reasoning","summary":[{"type":"summary_text","text":"I should run ls."}],"encrypted_content":"opaque"}}`,
  `{"type":"response_item","payload":{"type":"function_call","name":"shell_command","arguments":"{\\"command\\":\\"ls -la\\"}","call_id":"call_1"}}`,
  `{"type":"response_item","payload":{"type":"function_call_output","call_id":"call_1","output":"Exit code: 0\\nOutput:\\na.ts"}}`,
  `{"type":"event_msg","payload":{"type":"agent_message","message":"Listed the files."}}`,
].join("\n");

test("parseCodexTranscript recovers reasoning summary, tool call + output, agent message", () => {
  const ev = parseCodexTranscript(CODEX_RICH);
  assert.deepEqual(
    ev.map((e) => e.kind),
    ["user_message", "agent_thought", "tool_call", "tool_call_update", "agent_message"],
  );
  assert.equal(first(ev, "agent_thought").text, "I should run ls.");
  const call = first(ev, "tool_call");
  assert.equal(call.toolCallId, "call_1");
  assert.equal(call.title, "ls -la");
  assert.equal(call.toolKind, "execute");
  const out = first(ev, "tool_call_update");
  assert.equal(out.toolCallId, "call_1");
  assert.match(out.text ?? "", /a\.ts/);
});

test("parseCodexTranscript skips encrypted reasoning with no readable summary", () => {
  const enc = `{"type":"response_item","payload":{"type":"reasoning","summary":[],"encrypted_content":"opaque"}}`;
  assert.deepEqual(parseCodexTranscript(enc), []);
});

const CODEX_NARRATION = [
  `{"type":"response_item","payload":{"type":"message","role":"user","content":[{"type":"input_text","text":"go"}]}}`,
  `{"type":"event_msg","payload":{"type":"agent_message","message":"First I'll look around."}}`,
  `{"type":"response_item","payload":{"type":"function_call","name":"shell_command","arguments":"{\\"command\\":\\"ls\\"}","call_id":"c1"}}`,
  `{"type":"response_item","payload":{"type":"function_call_output","call_id":"c1","output":"a.ts"}}`,
  `{"type":"event_msg","payload":{"type":"agent_message","message":"Done — here is the summary."}}`,
].join("\n");

test("parseCodexTranscript folds per-step narration into reasoning, keeps the final answer", () => {
  const ev = parseCodexTranscript(CODEX_NARRATION);
  assert.deepEqual(
    ev.map((e) => e.kind),
    ["user_message", "agent_thought", "tool_call", "tool_call_update", "agent_message"],
  );
  // The message before the tool call is narration (folded to reasoning); the trailing one is the answer.
  assert.equal(first(ev, "agent_thought").text, "First I'll look around.");
  assert.equal(first(ev, "agent_message").text, "Done — here is the summary.");
});
